            half4  _Ink2;            // plate in coverage.g  (chevron deep)
            half4  _Ink3;            // plate in coverage.b  (accent band)
            half4  _Ink4;            // plate in coverage.a  (cream)
            float4 _PrintTile;       // xy metres per print repeat (x divides 192), zw print offset (m)
