            float4 _Misreg34;        // xy plate-3 offset (m), zw plate-4 offset (m)
            half   _PrintStrength;   // 0 = bare paper .. 1 = full print run
            half   _DotGainN;        // Yule-Nielsen n; 1 = Murray-Davies, ~2.2 = today's sRGB duotone
            half   _InkGloss;        // keep 0: otherwise the sheen follows the motion layer
            half   _GhostEmboss;     // 0..1 static chevron-registered emboss (_FR_PRINT_GHOST)
