        TEXTURE2D(_FR_PrintCoverage); SAMPLER(sampler_FR_PrintCoverage);

// ForwardLit pass only:
//  #pragma shader_feature_local_fragment _ _FR_PRINT
//  #pragma shader_feature_local_fragment _ _FR_PRINT_GHOST

// One ink plate laid over reflectance R (all linear, after sRGB decode).
//  ink.rgb : mass tone of the ink printed solid on white stock
//  ink.a   : opacity. 0 = transparent process ink (gravure/flexo): filters R.
//            1 = opaque body colour (surface / rotary screen): replaces R but keeps
//            the paper's fibre/mottle, because machine ink is only a film on the sheet.
//  c       : area coverage. Continuous coverage = halftone averaged over the pixel
//            (Murray-Davies). n > 1 adds Yule-Nielsen optical dot gain.
half3 PrintPlate(half3 R, half3 paperTex, half4 ink, half c, half n)
{
    half3 solid = lerp(R * ink.rgb, ink.rgb * paperTex, ink.a);
    half  k = rcp(max(n, 1.0h));
    return PositivePow(lerp(PositivePow(R, k), PositivePow(solid, k), saturate(c)), n);
}

// ---------------- inside Frag(), after `float2 uv = ...;` ----------------
#if defined(_FR_PRINT)
    // 1. SKIN (static). Everything the BRDF reads comes from here.
    half3 paper = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, uv).rgb;      // unprinted paper
    half4 mask  = SAMPLE_TEXTURE2D(_MaskMap, sampler_MaskMap, uv);          // R gloss G cavity B ageing A blot
    half3 nTS   = UnpackNormalScale(SAMPLE_TEXTURE2D(_BumpMap, sampler_BumpMap, uv), _BumpScale);
    half3 paperTex = paper / max(_PaperMean.rgb, 1e-3h);                   // mean-1 paper texture

    // 2. PRINT (motion layer). Albedo only; same world-planar frame as the paper,
    //    so it is glued to the wall. One sample per plate = per-plate misregistration.
    float2 inv = rcp(_PrintTile.xy);
    float2 puv = (metres + _PrintTile.zw) * inv;
    half4 cov;
    cov.r = SAMPLE_TEXTURE2D(_FR_PrintCoverage, sampler_FR_PrintCoverage, puv + _Misreg12.xy * inv).r;
    cov.g = SAMPLE_TEXTURE2D(_FR_PrintCoverage, sampler_FR_PrintCoverage, puv + _Misreg12.zw * inv).g;
    cov.b = SAMPLE_TEXTURE2D(_FR_PrintCoverage, sampler_FR_PrintCoverage, puv + _Misreg34.xy * inv).b;
    cov.a = SAMPLE_TEXTURE2D(_FR_PrintCoverage, sampler_FR_PrintCoverage, puv + _Misreg34.zw * inv).a;
    cov = saturate(cov) * _PrintStrength;

    // Press order: ground flood, then plates. With all plates opaque and n ~ 2.2
    // this reproduces today's duotone: ground->mid (2t), mid->deep (2t-1), cream.
    half3 R = PrintPlate(paper, paperTex, _InkGround, _PrintStrength, _DotGainN);
    R = PrintPlate(R, paperTex, _Ink1, cov.r, _DotGainN);
    R = PrintPlate(R, paperTex, _Ink2, cov.g, _DotGainN);
    R = PrintPlate(R, paperTex, _Ink3, cov.b, _DotGainN);
    R = PrintPlate(R, paperTex, _Ink4, cov.a, _DotGainN);

    // 3. ABOVE THE PRINT (static): transparent filters, so ink can never hide them.
    R *= mask.b;                                    // foxing + roll-seam shadow
    R *= lerp(1.0h, _PaperStainColor.rgb, mask.a);  // blots / old tide marks
    R *= _BaseColor.rgb;                            // yellowed topcoat / Shift tint
    half4 albedo = half4(R, 1.0h);
    mask.r += _InkGloss * dot(cov, 0.25h);          // default 0 - see notes

