    // Optional: the old chevron's emboss frozen in the skin.
    // _GhostMap: RG = emboss normal XY (linear), B = old-ink density.
    half4 gh  = SAMPLE_TEXTURE2D(_GhostMap, sampler_GhostMap, uv);
    half2 gxy = (gh.rg * 2.0h - 1.0h) * (_GhostEmboss * _BumpScale);
    nTS = BlendNormalRNM(nTS, half3(gxy, sqrt(saturate(1.0h - dot(gxy, gxy)))));
    mask.r += 0.07h * _GhostEmboss * gh.b;          // old ink was a touch glossier
    mask.g *= 1.0h - 0.10h * _GhostEmboss * gh.b;   // and sat in a shallow recess
  #endif
#else
    half4 albedo = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, uv) * _BaseColor;
    half4 mask = SAMPLE_TEXTURE2D(_MaskMap, sampler_MaskMap, uv);
    half3 nTS = UnpackNormalScale(SAMPLE_TEXTURE2D(_BumpMap, sampler_BumpMap, uv), _BumpScale);
