float4 _FR_PrintClock;  // x = frame position [0,n), y = n, z = per-roll phase (frames), w = wave delay (frames per metre)
float4 _FR_PrintWave;   // xyz = wave origin (world)
float4 _FR_PrintSize;   // xy = slice width/height in texels
// Inside UnityPerMaterial: half4 _InkColor; half _PrintAmount;

uint FR_Hash(uint x) { x ^= x >> 16; x *= 0x7feb352du; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16; return x; }

half FR_PrintInk(float2 tileUV, float3 positionWS)   // tileUV = metres / _TileSize.xy (continuous)
{
    float2 dx = ddx(tileUV), dy = ddy(tileUV);          // gradients from the continuous UV: no mip seam on roll lines
    int strip = (int)floor(tileUV.x);
    float h = (FR_Hash((uint)(strip & 3)) & 0xffffu) / 65535.0;   // & 3 keeps the 3 m module rule; & 255 = 192 m period
    float n = _FR_PrintClock.y;
    float f = _FR_PrintClock.x + h * _FR_PrintClock.z - distance(positionWS, _FR_PrintWave.xyz) * _FR_PrintClock.w;
    f -= n * floor(f / n);
    float i0 = floor(f), t = f - i0;
    float i1 = (i0 + 1.0 >= n) ? 0.0 : i0 + 1.0;
    half2 a = SAMPLE_TEXTURE2D_ARRAY_GRAD(_FR_Print, sampler_FR_Print, tileUV, i0, dx, dy).rg;
    half2 b = SAMPLE_TEXTURE2D_ARRAY_GRAD(_FR_Print, sampler_FR_Print, tileUV, i1, dx, dy).rg;
    half sdf = lerp(a.r, b.r, t) - 0.5h;                 // SDF lerp = morph, not ghosting
    half nearInk = saturate(sdf / max(fwidth(sdf), 1e-4) + 0.5h);
    half farInk = lerp(a.g, b.g, t);                     // mipped coverage = correct average far away
    float texelsPerPixel = max(length(dx * _FR_PrintSize.xy), length(dy * _FR_PrintSize.xy));
    return lerp(nearInk, farInk, saturate(texelsPerPixel - 1.0));
}

