using UnityEngine;

public sealed class FrontRoomsPrint : MonoBehaviour
{
    static readonly int PrintId = Shader.PropertyToID("_FR_Print");
    static readonly int ClockId = Shader.PropertyToID("_FR_PrintClock");
    static readonly int SizeId  = Shader.PropertyToID("_FR_PrintSize");

    [SerializeField] Texture2DArray print;          // linear, mips, aniso 16, Repeat
    [SerializeField] float keyframesPerSecond = 4f;  // SDF lerp tweens between keyframes
    [SerializeField] float rollPhaseFrames = 0f;     // 0 = all rolls in step
    [SerializeField] float waveFramesPerMetre = 0f;
    public float Speed = 1f;                         // 0 freezes the paper; events can spike or reverse it
    double clock;                                    // double + wrap: no drift in long sessions

    void OnEnable()
    {
        Shader.SetGlobalTexture(PrintId, print);     // bound once; never reallocate the texture
        Shader.SetGlobalVector(SizeId, new Vector4(print.width, print.height, 0f, 0f));
    }

    void Update()
    {
        int n = print.depth;                         // number of slices
        clock = (clock + Time.deltaTime * Speed * keyframesPerSecond) % n;
        if (clock < 0) clock += n;
        Shader.SetGlobalVector(ClockId, new Vector4((float)clock, n, rollPhaseFrames, waveFramesPerMetre));
    }
}

// Globals only: never in Properties / UnityPerMaterial, or the material value wins over Shader.SetGlobal*.
TEXTURE2D(_FR_PrintState);                                // 64x64 RGBA8 point/repeat: R cur variant, G prev variant, B progress, A kind
TEXTURE2D(_FR_PrintField); SAMPLER(sampler_FR_PrintField); // 64x64 RGBA8 bilinear/repeat: R light, G phosphor, B wave, A zone phase
float4 _FR_PrintClock;      // x drift phase [0,1), y breath phase [0,1), z dread 0..1, w seconds mod 64 (CPU-wrapped, double)
float4 _FR_Events[8];       // xy world XZ, z age (s, CPU double), w strength (0 = empty)
#define FR_CELL 3.0
#define FR_ROLL 0.75
#define FR_N    64          // 64 cells = 192 m = ModuleUnits.WorldPeriod

uint FR_Hash(uint v) { v = v * 747796405u + 2891336453u; v = ((v >> ((v >> 28u) + 4u)) ^ v) * 277803737u; return (v >> 22u) ^ v; }
float FR_Hash01(uint v) { return (FR_Hash(v) & 0xFFFFFFu) / 16777216.0; }

struct FRCtx { int2 texel; float2 fieldUV; int strip; uint stripKey; half4 state; half4 field; };

// u = PlanarFrame's metres.x (dot(positionWS, t)); nGeo = geometric normal.
FRCtx FR_Context(float3 positionWS, float3 nGeo, float u)
{
    FRCtx c;
    float2 probe = positionWS.xz + nGeo.xz * 0.5;      // a wall face belongs to the cell it faces
    int2 cell = (int2)floor(probe / FR_CELL);
    c.texel   = cell & (FR_N - 1);                       // world-anchored toroidal index: no scrolling
    c.fieldUV = probe / (FR_CELL * FR_N);                // repeat-wrapped, bilinear
    c.state   = LOAD_TEXTURE2D(_FR_PrintState, c.texel);
    c.field   = SAMPLE_TEXTURE2D_LOD(_FR_PrintField, sampler_FR_PrintField, c.fieldUV, 0);
    c.strip   = (int)floor(u / FR_ROLL);                 // seams on world multiples of 0.75 m, both faces
    int line  = (int)round(dot(positionWS, nGeo) / FR_CELL);
    // Periodic indices only (256 strips, 64 lines per 192 m): a 192 m shift leaves every hash unchanged.
    c.stripKey = (uint)(c.strip & 255) | ((uint)(line & 63) << 8)
               | ((abs(nGeo.x) > 0.5 ? 1u : 0u) << 14) | ((nGeo.x + nGeo.z > 0.0 ? 1u : 0u) << 15);
    return c;
}

half FR_Ring(float2 p)  // straight-line rings; corridor-following waves come from field.b instead
{
    half w = 0;
    [unroll] for (int i = 0; i < 8; i++)
    {
        float4 e = _FR_Events[i];
        float band = (distance(p, e.xy) - e.z * 7.0) / 1.2;   // 7 m/s front, 1.2 m wide
        w += (half)(e.w * exp(-band * band) * exp(-e.z / 1.6));
    }
    return saturate(w);
}

// Result feeds ONLY the motion layer (pattern UV / ink mix / emission); normalTS, smoothness, cavity stay paper-only.
half FR_Mask(FRCtx c, float u, float y, float ceilingY, half fibre)
{
    half kind = c.state.a * 255.0h, p = c.state.b;
    if (kind < 0.5h) return step(fibre, p);                                       // fibre dissolve (fibre from MaskMap A)
    if (kind < 1.5h) { half q = saturate((p - FR_Hash01(c.stripKey) * 0.5h) * 2.0h);
                       return step(ceilingY * (1.0 - q), y); }                      // strip wipe, top-down, staggered
    return step(frac(u / FR_CELL), p);                                           // reprint roll along the 3 m edge
}

// Reads map/Relay through public API only. Runs before the game camera renders, so a cell that
// comes into view mid-transition is snapped before its first visible frame.
void BeforeCamera(ScriptableRenderContext ctx, Camera cam)
{
    if (map == null || cam.cameraType != CameraType.Game || cam != Camera.main) return;
    double now = Time.timeAsDouble;
    MarkVisible(cam, (float)now);           // lastSeen[cell & 63] = now for every possibly visible cell
    TickCells(now);                         // advance only cells unseen >= hold (or lamp-masked); snap newly visible ones
    state.SetPixelData(st, 0); state.Apply(false);
    field.SetPixelData(fd, 0); field.Apply(false);
    Shader.SetGlobalVector(ClockId, new Vector4((float)(now / 96.0 % 1.0), (float)(now / 11.0 % 1.0), dread, (float)(now % 64.0)));
    for (int i = 0; i < events.Length; i++) events[i].z = (float)(now - eventT0[i]);   // ages, never absolute times
    Shader.SetGlobalVectorArray(EventsId, events);                                    // always the full 8
}

static int Index(GridCoord c) => (c.x & 63) + (c.y & 63) * 64;   // map root on a 192 m multiple => world & 63 == map & 63

void MarkVisible(Camera cam, float now)
{
    GeometryUtility.CalculateFrustumPlanes(cam, planes);           // non-alloc Plane[6]
    var start = map.CellOf(cam.transform.position);
    seen.Clear(); open.Clear(); seen.Add(start); open.Enqueue(start);
    while (open.Count > 0)
    {
        var c = open.Dequeue();
        lastSeen[Index(c)] = now;
        foreach (var d in Steps)                                    // (1,0) (-1,0) (0,1) (0,-1)
        {
            var n = c + d;
            if (seen.Contains(n) || !map.IsBuilt(n) || !SeeThrough(c, n)) continue;
            bool near = Mathf.Abs(n.x - start.x) <= 1 && Mathf.Abs(n.y - start.y) <= 1;
            var box = new Bounds(map.CellCenter(n) + Vector3.up * 2.7f, new Vector3(3.2f, 5.6f, 3.2f));
            if (!near && !GeometryUtility.TestPlanesAABB(planes, box)) continue;   // far plane (46 m) culls too
            seen.Add(n); open.Enqueue(n);
        }
    }
}

bool SeeThrough(GridCoord a, GridCoord b)
{
    switch (map.PassageBetween(a, b))
    {
        case FrontRoomsMapWorld.Passage.Open:
        case FrontRoomsMapWorld.Passage.Glass: return true;          // glass is transparent
        case FrontRoomsMapWorld.Passage.ClosedDoor:                   // reported until progress > 0.6: be conservative
            var door = map.DoorBetween(a, b); return door != null && (door.open || door.progress > 0f);
        default: return false;
    }
}

