// Outside the CBUFFER. Globals must NOT appear in Properties.
TEXTURE2D(_PrintMap);                    // static print (P0), set on the material
TEXTURE2D(_PrintPalette);  SAMPLER(sampler_PrintPalette); // 256xN ramp, clamp
TEXTURE2D_ARRAY(_FR_PrintFrames);        // P1+: global flipbook (BC4, offline mips)
float4 _FR_PrintParams;  // x frameA, y frameB, z blend, w liveMix (unset = 0 -> static)
