// In Frag, replacing the albedo line (#if defined(_FR_PRINT)):
half3 paper = SAMPLE_TEXTURE2D(_BaseMap, sampler_BaseMap, uv).rgb;   // paper tone only
half ink = SAMPLE_TEXTURE2D(_PrintMap, sampler_BaseMap, uv).r;       // reuse aniso16/trilinear/repeat
UNITY_BRANCH if (_FR_PrintParams.w > 0)
{
    float2 uvLive = uv + _FR_PrintScroll.xy;
    half a = SAMPLE_TEXTURE2D_ARRAY(_FR_PrintFrames, sampler_BaseMap, uvLive, _FR_PrintParams.x).r;
    half b = SAMPLE_TEXTURE2D_ARRAY(_FR_PrintFrames, sampler_BaseMap, uvLive, _FR_PrintParams.y).r;
    ink = lerp(ink, lerp(a, b, (half)_FR_PrintParams.z), (half)_FR_PrintParams.w);
}
half3 printRGB = SAMPLE_TEXTURE2D(_PrintPalette, sampler_PrintPalette, float2(ink, _PaletteRow)).rgb;
half4 albedo = half4(printRGB * paper, 1) * _BaseColor;
// mask, nTS, smoothness and cavity stay exactly as now (paper maps only); the macro wear lines follow unchanged.

static readonly int ParamsId = Shader.PropertyToID("_FR_PrintParams");
static readonly int ScrollId = Shader.PropertyToID("_FR_PrintScroll");
double printClock;            // advanced by game state; pausable, scrubbable, seedable

void LateUpdate()
{
    printClock += Time.unscaledDeltaTime * rate;            // never Time.time / _Time
    double f = printClock * framesPerSecond;
    int a = (int)(f % frameCount), b = (a + 1) % frameCount;
    float blend = (float)(f - System.Math.Floor(f));
    Shader.SetGlobalVector(ParamsId, new Vector4(a, b, blend, liveMix));
    double sx = (printClock * scrollTilesPerSecond) % 1.0;   // wrap in double, pass [0,1)
    Shader.SetGlobalVector(ScrollId, new Vector4((float)sx, 0f, 0f, 0f));
}

